const DISCLAIMER_PATTERNS = [
  /prior results do not guarantee[^.]*\./gi,
  /past results (do not|don't) guarantee[^.]*\./gi,
  /testimonials do not constitute[^.]*\./gi,
  /results (may )?var(y|ies)[^.]*\./gi,
  /every case is different[^.]*\./gi,
  /no (representation|guarantee) is made[^.]*\./gi,
];

function stripDisclaimers(text) {
  let stripped = text;
  const found = [];
  for (const p of DISCLAIMER_PATTERNS) {
    const m = stripped.match(p);
    if (m) found.push(...m.map(s => s.trim()));
    stripped = stripped.replace(p, ' ');
  }
  return { stripped, disclaimers: found };
}

const BASE_RULES = [
  {
    code: 'SUPERLATIVE',
    severity: 'blocking',
    basis: 'ABA Model Rule 7.1 - unverifiable comparative claim',
    patterns: [
      /\bbest\b(?!\s+(?:interests?|practices?))/i,
      /#\s?1\b/,
      /\bnumber one\b/i,
      /\btop[-\s]rated\b/i,
      /\bpremier\b/i,
      /\b(finest|greatest)\b/i,
      /\bmost successful\b/i,
      /\bunmatched|unparalleled\b/i,
    ],
  },
  {
    code: 'SPECIALIST',
    severity: 'blocking',
    basis: 'ABA Model Rule 7.4 - specialist claim without accredited certification',
    patterns: [
      /\bspecial(?:ist|ists|ize|izes|izing|ization)\b/i,
      /(?<!\b(?:witness|reconstruction|forensic|medical|vocational|economic)\s)\bexperts?\b(?!\s+(?:witness|witnesses|testimony|report))/i,
    ],
  },
  {
    code: 'GUARANTEE',
    severity: 'blocking',
    basis: 'ABA Model Rule 7.1 - guarantee or prediction of outcome',
    patterns: [
      /\bguarantee[sd]?\b/i,
      /\bwe will win\b/i,
      /\bwe (?:do not|don't|never) lose\b/i,
      /\bpromise\b/i,
    ],
  },
];

const CONDITIONAL_RULES = [
  {
    code: 'RESULTS_NO_DISCLAIMER',
    severity: 'review',
    basis: 'Most jurisdictions require a results disclaimer alongside verdict or settlement figures',
    test: (s, ctx) => (/\$[\d,]+(?:\.\d+)?\s*(?:million|billion|m\b|k\b)?/i.test(s)
      || /\b(?:millions|billions)\b/i.test(s)) && ctx.disclaimers.length === 0,
  },
  {
    code: 'TESTIMONIAL_NO_DISCLAIMER',
    severity: 'review',
    basis: 'Client testimonial presented without required disclaimer',
    test: (s, ctx) => /["“][^"”]{15,}["”]\s*[-–—]\s*\S/.test(s) && ctx.disclaimers.length === 0,
  },
  {
    code: 'SPECIALIST_CERT_UNNAMED',
    severity: 'blocking',
    basis: 'Certification claimed without naming the certifying organization',
    test: (s) => /\bboard[-\s]certified\b/i.test(s) && !/certified by\s+the\s+\S+/i.test(s),
  },
];

const STATE_RULES = {
  NY: [{
    code: 'MISSING_ATTY_AD_LABEL',
    severity: 'blocking',
    basis: "NY Rule 7.1(f) - advertising must be labeled 'Attorney Advertising'",
    test: (s) => !/attorney advertising/i.test(s),
  }],
  FL: [{
    code: 'FL_PREFILING_REVIEW',
    severity: 'advisory',
    basis: 'Florida Bar requires pre-publication review for many advertisement types',
    test: (s) => /\$[\d,]+/.test(s) || /\bverdict|settlement\b/i.test(s),
  }],
};

const item = $input.item.json;
const { stripped, disclaimers } = stripDisclaimers(item.content);
const ctx = { disclaimers };
const hits = [];

for (const rule of BASE_RULES) {
  for (const p of rule.patterns) {
    const m = stripped.match(p);
    if (m) {
      hits.push({ code: rule.code, severity: rule.severity, basis: rule.basis,
                  matched_text: m[0].trim(), layer: 'deterministic' });
      break;
    }
  }
}

for (const rule of [...CONDITIONAL_RULES, ...(STATE_RULES[item.state] || [])]) {
  if (rule.test(stripped, ctx)) {
    hits.push({ code: rule.code, severity: rule.severity, basis: rule.basis,
                matched_text: null, layer: 'deterministic' });
  }
}

// v2 prompt (eval harness, 2026-09-23): the codes match the answer key's names, and the
// confidence scale is anchored. v1 told the model to "be conservative", and it hedged the
// confidence of findings it did report: true implied violations came back at 0.55-0.85,
// under the client thresholds (0.80-0.90), so they became notes instead of reviews.
// Conservatism now applies to WHETHER to report, not to how confident a report is.
const llm_prompt = 'You are reviewing marketing copy for a law firm advertising in ' + item.state + ' (practice area: ' + item.practice_area + ').\n\n' +
  'Your job is to find violations of attorney advertising rules that a keyword scanner CANNOT catch - claims that are problematic because of what they IMPLY, not because of any specific banned word.\n\n' +
  'Look for:\n' +
  '- IMPLIED_GUARANTEE: language creating an unjustified expectation of a particular outcome, without using the word "guarantee"\n' +
  '- IMPLIED_SUPERIORITY: claims of being better than other firms, without using a superlative\n' +
  '- UNVERIFIABLE_COMPARISON: comparisons to other lawyers that cannot be factually substantiated\n' +
  '- STATISTIC_NO_CONTEXT: success rates or percentages presented without the context needed to interpret them\n' +
  '- AWARD_CLAIM_REVIEW: awards, rankings, or list placements that may require naming the granting organization and its selection methodology\n' +
  '- TESTIMONIAL_NO_DISCLAIMER: client testimonials presented without a disclaimer, or implying typical results\n' +
  '- RESULTS_NO_DISCLAIMER: described outcomes (even non-monetary) presented without a results disclaimer\n\n' +
  'Do NOT report simple banned keywords such as "best", "#1", "specialist", "expert", or "guarantee" - a separate deterministic layer already handles those. Report only implied or contextual problems.\n\n' +
  'Report a finding only if a bar compliance reviewer would ask for the copy to be changed. A false positive trains the content team to ignore this system, so if copy is factual, verifiable, and makes no outcome promise, return an empty findings array.\n\n' +
  'Do not hedge the confidence of a finding you do report. The confidence decides whether a person must review the copy before it is published: understating it lets a real violation go live with only a note.\n\n' +
  'COPY TO REVIEW:\n"""\n' + item.content + '\n"""\n\n' +
  'Respond with ONLY valid JSON, no preamble or code fences, in exactly this shape:\n' +
  '{"findings": [{"code": "IMPLIED_GUARANTEE", "quote": "the exact span of text at issue", "reasoning": "one sentence on why this implies something the rules prohibit", "confidence": 0.0}]}\n' +
  'Set confidence to your probability that a bar compliance reviewer would agree this is a violation, using these anchors:\n' +
  '- 0.90 to 1.00: the copy plainly promises or strongly implies an outcome, superiority, or result without the required context; most reviewers would flag it on sight\n' +
  '- 0.70 to 0.89: a reasonable reviewer would probably flag it, but it depends on the wording or context\n' +
  '- 0.50 to 0.69: arguable; some reviewers would flag it, many would not\n' +
  '- below 0.50: do not report it';

return {
  json: {
    ...item,
    deterministic_hits: hits,
    disclaimers_found: disclaimers,
    llm_prompt,
  },
};

const src = $('Layer 1 Deterministic Scan').item.json;
const resp = $input.item.json;

let llm_findings = [];
let llm_status = 'ok';
let usage = { input_tokens: 0, output_tokens: 0 };

try {
  if (resp.error) throw new Error(resp.error.message || 'api error');

  // Models with adaptive thinking return content as an array of blocks, and a
  // thinking block can come first. Find the text block by type; never assume [0].
  const blocks = Array.isArray(resp.content) ? resp.content : [];
  const textBlock = blocks.find(b => b && b.type === 'text');
  const raw = textBlock && textBlock.text;
  if (!raw) throw new Error('no text block in response (blocks: ' + blocks.map(b => b && b.type).join(',') + ')');

  usage = resp.usage || usage;

  const cleaned = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  const parsed = JSON.parse(cleaned);
  llm_findings = Array.isArray(parsed.findings) ? parsed.findings : [];
} catch (e) {
  llm_status = 'error: ' + e.message;
}

const threshold = src.auto_pass_threshold;
const gating_llm = llm_findings.filter(f => (f.confidence ?? 0) >= threshold);
const advisory_llm = llm_findings.filter(f => (f.confidence ?? 0) < threshold);
const blocking_det = src.deterministic_hits.filter(h => h.severity === 'blocking');
const review_det = src.deterministic_hits.filter(h => h.severity === 'review');
const advisory_det = src.deterministic_hits.filter(h => h.severity === 'advisory');

let decision;
let decision_reason;

if (llm_status !== 'ok') {
  decision = 'REVIEW_REQUIRED';
  decision_reason = 'Layer 2 unavailable - failing safe to human review';
} else if (blocking_det.length > 0) {
  decision = 'BLOCK';
  decision_reason = 'Deterministic blocking rule(s): ' + blocking_det.map(h => h.code).join(', ');
} else if (review_det.length > 0 || gating_llm.length > 0) {
  decision = 'REVIEW_REQUIRED';
  decision_reason = [...review_det.map(h => h.code), ...gating_llm.map(f => f.code + ' (' + f.confidence + ')')].join(', ');
} else if (advisory_det.length > 0 || advisory_llm.length > 0) {
  decision = 'PASS_WITH_NOTES';
  decision_reason = [...advisory_det.map(h => h.code), ...advisory_llm.map(f => f.code + ' (' + f.confidence + ', below ' + threshold + ')')].join(', ');
} else {
  decision = 'PASS';
  decision_reason = 'No findings';
}

const all_codes = [...src.deterministic_hits.map(h => h.code), ...gating_llm.map(f => f.code)];
const cost_usd = (usage.input_tokens / 1e6) * 2 + (usage.output_tokens / 1e6) * 10;

return {
  json: {
    id: src.id,
    client_id: src.client_id,
    state: src.state,
    content: src.content,
    decision,
    decision_reason,
    flagged: decision !== 'PASS',
    deterministic_hits: src.deterministic_hits,
    llm_findings,
    llm_status,
    gating_codes: all_codes,
    expected_violations: src.expected_violations,
    expected_flag: src.expected_flag,
    detectable_by: src.detectable_by,
    input_tokens: usage.input_tokens,
    output_tokens: usage.output_tokens,
    cost_usd: Number(cost_usd.toFixed(6)),
    reviewed_at: new Date().toISOString(),
  },
};

// Scores this run against the answer key carried through the pipeline.
//
// Headline: the silent error rate. Of the documents that went out without review, the
// share the answer key says needed a person. PASS_WITH_NOTES goes out without review (its
// notes go to the Pass-with-Notes Log, which nobody reads before publishing), so a
// violation that only got a note counts as MISSED here, not caught.
// An earlier version counted a note as a catch and reported a 100% catch rate while
// 22-30% of the copy that went out needed a person (eval harness, 2026-09-23).
const rows = $input.all().map(i => i.json);

// A person sees these before anything is published. Everything else goes out without review.
const REVIEWED = ['BLOCK', 'REVIEW_REQUIRED'];
const isReviewed = r => REVIEWED.includes(r.decision);

const pct = (n, d) => d === 0 ? null : Number(((n / d) * 100).toFixed(1));
const excerpt = r => r.content.slice(0, 80);

const wentOut = rows.filter(r => !isReviewed(r));
const silentErrors = wentOut.filter(r => r.expected_flag);        // went out, but needed a person
const reviewed = rows.filter(isReviewed);
const violations = rows.filter(r => r.expected_flag);
const caught = violations.filter(isReviewed);                     // violations a person saw
const clean = rows.filter(r => !r.expected_flag);
const falseAlarms = clean.filter(isReviewed);                      // clean copy a person had to check

// Which layer found each violation that reached a person.
let det_only = 0, llm_only = 0, both = 0;
for (const r of caught) {
  const d = r.deterministic_hits.length > 0;
  const l = (r.llm_findings || []).length > 0;
  if (d && l) both++; else if (d) det_only++; else if (l) llm_only++;
}

const total_cost = rows.reduce((s, r) => s + (r.cost_usd || 0), 0);
const total_in = rows.reduce((s, r) => s + (r.input_tokens || 0), 0);
const total_out = rows.reduce((s, r) => s + (r.output_tokens || 0), 0);
const errors = rows.filter(r => r.llm_status !== 'ok').length;
const byDecision = rows.reduce((acc, r) => { acc[r.decision] = (acc[r.decision] || 0) + 1; return acc; }, {});

return [{
  json: {
    run_at: new Date().toISOString(),
    documents_evaluated: rows.length,
    headline: {
      silent_error_rate_pct: pct(silentErrors.length, wentOut.length),
      silent_errors: silentErrors.length,
      went_out_without_review: wentOut.length,
      note: 'Of the documents that went out without review (PASS and PASS_WITH_NOTES), the share the answer key says needed a person. Each one reached the public with nobody having looked.',
    },
    accuracy: {
      catch_rate_pct: pct(caught.length, violations.length),
      violations: violations.length,
      caught_by_a_person: caught.length,
      went_out_with_only_a_note: silentErrors.filter(r => r.decision === 'PASS_WITH_NOTES').length,
      went_out_with_nothing: silentErrors.filter(r => r.decision === 'PASS').length,
      false_alarm_rate_pct: pct(falseAlarms.length, clean.length),
      false_alarms: falseAlarms.length,
      clean_documents: clean.length,
      review_precision_pct: pct(reviewed.length - falseAlarms.length, reviewed.length),
      note: 'Catch rate: violations that reached a person, out of all violations. A note does not count: the copy still went out. False alarm rate: clean copy a person had to check. Review precision: reviews a person actually needed.',
    },
    layer_attribution: {
      caught_by_deterministic_only: det_only,
      caught_by_llm_only: llm_only,
      caught_by_both: both,
      note: 'Of the violations that reached a person, which layer found them. llm_only is what regex structurally could not find; if it is 0, the LLM layer is not earning its cost.',
    },
    routing: {
      by_decision: byDecision,
      straight_through_pct: pct(wentOut.length, rows.length),
      note: 'Straight-through: the share that went out without review (PASS and PASS_WITH_NOTES). Meaningless alone; read it beside the silent error rate.',
    },
    reliability: {
      llm_errors: errors,
      error_rate_pct: pct(errors, rows.length),
      note: 'A document whose model call failed goes to a person, never out without review.',
    },
    cost: {
      total_usd: Number(total_cost.toFixed(4)),
      per_document_usd: Number((total_cost / rows.length).toFixed(6)),
      input_tokens: total_in,
      output_tokens: total_out,
      projected_usd_per_1000_docs: Number(((total_cost / rows.length) * 1000).toFixed(2)),
    },
    silent_errors: silentErrors.map(r => ({
      id: r.id,
      decision: r.decision,
      expected: r.expected_violations,
      found_below_threshold: (r.llm_findings || []).map(f => f.code + ' (' + f.confidence + ')'),
      excerpt: excerpt(r),
    })),
    false_alarms: falseAlarms.map(r => ({ id: r.id, decision: r.decision, why: r.decision_reason, excerpt: excerpt(r) })),
  },
}];

// One row per note on every PASS_WITH_NOTES document, for the Pass-with-Notes Log.
// A note is a finding the workflow recorded but did not act on: an LLM finding below the
// client's threshold, or an advisory rule. PASS_WITH_NOTES copy goes live without a person,
// so this log is the only place those findings are seen. One row per note (not per
// document), so sorting the log by code shows which problems keep coming back.
const thresholds = {};
for (const i of $('Load Clients and Eval Set').all()) thresholds[i.json.id] = i.json.auto_pass_threshold;

const rows = [];
for (const { json: r } of $input.all()) {
  if (r.decision !== 'PASS_WITH_NOTES') continue;
  const threshold = thresholds[r.id] ?? null;
  // Eval-set documents carry an answer key; live copy does not.
  const hasKey = Array.isArray(r.expected_violations);
  const base = {
    doc_id: r.id,
    client_id: r.client_id,
    state: r.state,
    threshold,
    content: r.content,
    source: hasKey ? 'golden 500' : 'live',
    key_verdict: hasKey ? (r.expected_flag ? 'violation' : 'clean') : '',
    key_codes: hasKey ? r.expected_violations.join(', ') : '',
    run_id: String($execution.id),
    reviewed_at: r.reviewed_at,
  };
  // PASS_WITH_NOTES means no finding cleared its bar: every LLM finding is below the
  // threshold and every deterministic hit is advisory.
  for (const f of r.llm_findings || []) {
    const c = typeof f.confidence === 'number' ? f.confidence : null;
    rows.push({ ...base, code: f.code, layer: 'llm', confidence: c,
      short_by: c !== null && threshold !== null ? Number((threshold - c).toFixed(2)) : null,
      quote: f.quote || '', reasoning: f.reasoning || '' });
  }
  for (const h of r.deterministic_hits || []) {
    rows.push({ ...base, code: h.code, layer: 'deterministic', confidence: null, short_by: null,
      quote: h.matched_text || '', reasoning: h.basis || '' });
  }
}
return rows.map(json => ({ json }));
